import {permanentRates,permanentAttribute,combatAttribute,resistanceFor} from './attributes.mjs';
import {maxHp,effectiveStats,combatRates} from './combat.mjs';
export function attributeGuide(s,open=false){const r=combatRates(s),rows=[['최대 체력',maxHp(s),'999','체력이 소진되면 전투에서 패배합니다.'],...Object.entries({skill:'근력',insight:'민첩',control:'지능',charisma:'매력'}).map(([id,name])=>[name,combatAttribute(s,id),'60',{skill:'무기와 즉시 타격의 위력. 스킬별 계수를 확인하세요.',insight:'명중·회피·치명타·속도와 정밀 스킬에 영향.',control:'주문·방어와 일부 스킬의 위력에 영향.',charisma:'즉시 회복 스킬에 10당 회복 +1. 일부 능력의 전투 중 보정에 영향.'}[id]]),['치명타율',Math.round(r.critical*100)+'%','60%','치명타 기본 피해는 160%. 능력이 확률과 피해를 변경할 수 있습니다.'],['회피율',Math.round(r.evasion*100)+'%','60%','타격을 피하면 해당 타격의 피해를 받지 않습니다.'],...['burn','poison','bleed'].map(id=>[({burn:'발화 저항',poison:'중독 저항',bleed:'출혈 저항'})[id],Math.round(resistanceFor(s,id)*100)+'%','60%','해당 상태이상이 적용될 때 저항할 확률.'])];return `<details class="stat-guide" ${open?'open':''}><summary>능력치와 저항 · 효과·상한</summary><div class="stat-guide-body"><div class="attribute-table">${rows.map(([name,value,cap,note])=>`<div><strong>${name}</strong><b>${value}</b><small>기본 상한 ${cap}</small><p>${note}</p></div>`).join('')}</div><p>장비와 영구 성장에는 기본 상한을 적용합니다. 전투 중 능력·상태 효과는 이 상한을 초과할 수 있으며, 확률의 실제 판정은 최대 100%입니다.</p><p>코인은 전투 능력치가 아닙니다. 선택지·상점에서 사용하며, 최종 점수에는 보유 코인 중 최대 5,000개를 1개당 1점으로 더합니다.</p></div></details>`;}
